local HoundBreeder = {}
local PRODUCTS = {
    hunting_hound = { name = "Lovski pes", houndPupCost = 1, meatCost = 1, time = 3, cost = 30, yield = 40, prestige = 1, description = "Lovski pes za spremljanje lovcev." },
    tracking_hound = { name = "Sledilni pes", houndPupCost = 1, meatCost = 1, time = 4, cost = 55, yield = 50, prestige = 2, description = "Sledilni pes za iskanje plena." },
    greyhound = { name = "Hrt", houndPupCost = 1, meatCost = 2, time = 5, cost = 110, yield = 60, prestige = 4, happiness = 1, description = "Hrt za hitre lovv." },
    silver_coated_hound = { name = "Srebrnodlaki pes", houndPupCost = 1, silverCost = 1, meatCost = 2, time = 8, cost = 260, yield = 75, prestige = 9, happiness = 2, description = "Srebrnodlaki pes za plemiče." },
    silver_collar_hound = { name = "Srebrno ovratnični pes", houndPupCost = 1, silverCost = 1, meatCost = 2, time = 11, cost = 560, yield = 88, prestige = 15, happiness = 3, description = "Pes s srebrno ovratnico za visoke plemiče." },
    royal_grand_hound = { name = "Kraljevski veliki pes", houndPupCost = 2, goldCost = 1, silverCost = 1, jewelCost = 1, meatCost = 3, time = 16, cost = 1700, yield = 100, prestige = 40, happiness = 9, description = "Veliki kraljevski pes z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Pasja postaja", cost = { gold = 240, wood = 120, stone = 200 }, upkeep = 6, qualityBonus = 5 },
    kennel = { name = "Pasjak", cost = { gold = 850, wood = 250, stone = 350, meat = 10 }, upkeep = 21, qualityBonus = 18 },
    training_yard = { name = "Dresurni dvori", cost = { gold = 2200, wood = 350, stone = 600, silver = 25, leather = 8 }, upkeep = 55, qualityBonus = 30 },
    royal_hound_atelier = { name = "Kraljevski atelje pasje reje", cost = { gold = 8800, wood = 600, stone = 900, gold = 60, jewel = 20 }, upkeep = 175, qualityBonus = 55, prestigeBonus = 40 },
}
HoundBreeder.houndPupStock = 22; HoundBreeder.meatStock = 24; HoundBreeder.silverStock = 8; HoundBreeder.goldStock = 6; HoundBreeder.jewelStock = 6
HoundBreeder.productStock = {}; HoundBreeder.buildings = {}; HoundBreeder.maker = nil; HoundBreeder.activeMaking = {}; HoundBreeder.totalProducts = 0; HoundBreeder.dayTimer = 0
function HoundBreeder.init() HoundBreeder.houndPupStock=22; HoundBreeder.meatStock=24; HoundBreeder.silverStock=8; HoundBreeder.goldStock=6; HoundBreeder.jewelStock=6; HoundBreeder.productStock={}; HoundBreeder.buildings={}; HoundBreeder.maker=nil; HoundBreeder.activeMaking={}; HoundBreeder.totalProducts=0; HoundBreeder.dayTimer=0; print("[HoundBreeder] Royal Hound Breeder System initialized (6 products, 4 buildings)") end
function HoundBreeder.hireMaker(n,s) s=s or math.random(50,90); local c=500+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; HoundBreeder.maker={name=n or ("Pasar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pasar najet: %s (spretnost: %d)",HoundBreeder.maker.name,s),"success") end; return true end
function HoundBreeder.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function HoundBreeder.build(id) local ok,e=HoundBreeder.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(HoundBreeder.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function HoundBreeder.getQualityBonus() local b=0; for _,bd in ipairs(HoundBreeder.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function HoundBreeder.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.houndPupCost and HoundBreeder.houndPupStock<(d.houndPupCost or 0) then return false,"Premalo psičkov" end; if d.meatCost and HoundBreeder.meatStock<(d.meatCost or 0) then return false,"Premalo mesa" end; if d.silverCost and HoundBreeder.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and HoundBreeder.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and HoundBreeder.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #HoundBreeder.buildings==0 then return false,"Potrebna delavnica" end; if not HoundBreeder.maker then return false,"Potreben pasar" end; return true end
function HoundBreeder.make(pt,qty) qty=qty or 1; local ok,e=HoundBreeder.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.houndPupCost then HoundBreeder.houndPupStock=HoundBreeder.houndPupStock-d.houndPupCost*qty end; if d.meatCost then HoundBreeder.meatStock=HoundBreeder.meatStock-d.meatCost*qty end; if d.silverCost then HoundBreeder.silverStock=HoundBreeder.silverStock-d.silverCost*qty end; if d.goldCost then HoundBreeder.goldStock=HoundBreeder.goldStock-d.goldCost*qty end; if d.jewelCost then HoundBreeder.jewelStock=HoundBreeder.jewelStock-d.jewelCost*qty end; local t=d.time; if HoundBreeder.maker then t=math.max(1,t-math.floor(HoundBreeder.maker.skill/12)) end; table.insert(HoundBreeder.activeMaking,{id="hound_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,yield=d.yield or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function HoundBreeder.completeMaking(m) local q=1.0+(HoundBreeder.getQualityBonus()/100); if HoundBreeder.maker then q=q+(HoundBreeder.maker.skill/180) end; q=math.min(2.0,q); HoundBreeder.productStock[m.productType]=(HoundBreeder.productStock[m.productType] or 0)+m.quantity; HoundBreeder.totalProducts=HoundBreeder.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if HoundBreeder.maker then HoundBreeder.maker.itemsMade=HoundBreeder.maker.itemsMade+m.quantity; if math.random()<0.20 then HoundBreeder.maker.skill=math.min(100,HoundBreeder.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pes vzrejen: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"hound.completed",{productName=m.productName,yield=m.yield,prestige=m.prestige,happiness=m.happiness}) end end
function HoundBreeder.update(dt) if not _G.state then return end; HoundBreeder.dayTimer=HoundBreeder.dayTimer+dt; if HoundBreeder.dayTimer>=30 then HoundBreeder.dayTimer=0; for i=#HoundBreeder.activeMaking,1,-1 do local m=HoundBreeder.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then HoundBreeder.completeMaking(m); table.remove(HoundBreeder.activeMaking,i) end end; local tu=0; for _,bd in ipairs(HoundBreeder.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if HoundBreeder.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function HoundBreeder.getStats() return {houndPupStock=HoundBreeder.houndPupStock,meatStock=HoundBreeder.meatStock,silverStock=HoundBreeder.silverStock,goldStock=HoundBreeder.goldStock,jewelStock=HoundBreeder.jewelStock,productStock=HoundBreeder.productStock,numBuildings=#HoundBreeder.buildings,hasMaker=HoundBreeder.maker~=nil,makerName=HoundBreeder.maker and HoundBreeder.maker.name or "—",makerSkill=HoundBreeder.maker and HoundBreeder.maker.skill or 0,activeMaking=#HoundBreeder.activeMaking,totalProducts=HoundBreeder.totalProducts} end
return HoundBreeder
